insert into challenges (id, nom, description, ordre_affichage) values
  ('marathon-4', 'Marathon 4', 'Programme progressif d''étirements et de travail postural, semaine après semaine.', 1),
  ('marathon-3', 'Marathon 3', 'Gymnastique quotidienne, brossage à sec et exercices de gymnastique faciale.', 2),
  ('posture-challenge', 'Posture Challenge', 'Routines courtes pour la posture : lit, mur, épaules et omoplates.', 3),
  ('feet-challenge', 'Feet Challenge', 'Libération myofasciale, gymnastique et automassage des pieds.', 4)
insert into exercises (id, challenge_id, semaine, jour, ordre, titre, video_id, duree_min, categorie, materiel, texte) values
  ('s1j1o1', 'marathon-4', 1, 1, 1, 'Jour 1 — Ouverture et respiration', 'lCdgp09q9RI', 11, 'étirements', 'Coussin', 'Séance d''introduction pour entrer en douceur dans la routine. Travail au sol, ouverture de la cage thoracique et respiration. Stabilisation du bassin. Un coussin sous les ischions aide à tenir la position 90-90 sans forcer.'),
  ('s1j2o2', 'marathon-4', 1, 2, 2, 'Jour 2 — Alignement du bassin', 'TxbmEp2XaxM', 11, 'étirements', 'Coussin', 'Attention portée à la position du bassin : éviter toute bascule, garder un axe neutre. Vigilance sur l''épaule si un appui du bras est utilisé. Respiration continue tout au long de la pratique.'),
  ('s1j3o3', 'marathon-4', 1, 3, 3, 'Jour 3 — Posture et engagement du bassin', 'FMMp_H3T89E', 11, 'étirements', 'Coussin', 'Travail sur la posture puis engagement progressif du bassin pour construire soutien et contrôle. Suivre attentivement les consignes techniques du guide vidéo.'),
  ('s1j4o4', 'marathon-4', 1, 4, 4, 'Jour 4 — Mobilité de la cage thoracique', 'dI7aPB2tDoc', 9, 'étirements', 'Coussin', 'La cage thoracique entre en jeu. Poursuite du travail sur le bassin avec le coussin en appui. Amélioration de la mobilité costale et étirements doux pour plus d''espace dans le corps.'),
  ('s1j5o5', 'marathon-4', 1, 5, 5, 'Jour 5 — Travail avec les balles', '6C8PwMqQAk0', 15, 'étirements', 'Myo balles, ballon', 'Premier travail en profondeur avec les balles. Maintenir un axe corporel clair, s''allonger continuellement, éviter la bascule du bassin, rester attentif à la respiration.'),
  ('s1j5o6', 'marathon-4', 1, 5, 6, 'Jour 5 (bonus) — Ouverture du diaphragme', '7wtl4KpG9aU', 3, 'étirements', 'Myo balles, ballon', 'Vidéo optionnelle au sol pour approfondir le travail du diaphragme.'),
  ('s1j6o7', 'marathon-4', 1, 6, 7, 'Jour 6 — Rouleau de mousse, bas du corps', 'I7IpEF4Lt_E', 14, 'étirements', 'Foam roller', 'Travail au sol avec un rouleau en mousse lisse (sans relief). Focus sur le bas du corps, le tractus ilio-tibial, la région pelvienne et les zones lymphatiques de l''aine.'),
  ('s2j1o8', 'marathon-4', 2, 1, 8, 'Semaine 2, jour 1 — Reconnexion et respiration', 'nkDxgTmJWO0', 15, 'étirements', '', 'Premier jour de la semaine 2. Restauration de la connexion au corps, activation des muscles profonds, régulation de la respiration. Attention à l''axe du corps : tête relevée, nuque allongée.'),
  ('s2j1o9', 'marathon-4', 2, 1, 9, 'Semaine 2, jour 1 (bonus) — Posture C7', 'xv3_v50B5O8', 4, 'étirements', 'Myo balles', 'Vidéo optionnelle mais recommandée. Travail avec la balle puis exercices de posture (vertèbre C7, exercice ''Frame'', exercice anti text-neck) à ajouter en fin de séance, environ 20 secondes chacun.'),
  ('s2j2o10', 'marathon-4', 2, 2, 10, 'Semaine 2, jour 2 — Cage thoracique et diaphragme', 'GvvEST4sNcA', 12, 'étirements', 'Bande de résistance, serviette', 'Libération de la cage thoracique et restauration d''une respiration diaphragmatique fonctionnelle. Améliore la circulation, la posture et le drainage lymphatique.'),
  ('s2j3o11', 'marathon-4', 2, 3, 11, 'Semaine 2, jour 3 — Bassin et fessiers', 'AxJ-mK9xoo8', 13, 'étirements', 'Myo balles', 'Travail des fessiers et des ischions pour relâcher les tensions chroniques qui impactent le bas du dos. Séance assise évoluant vers une activation musculaire plus profonde.'),
  ('s2j4o12', 'marathon-4', 2, 4, 12, 'Semaine 2, jour 4 — Mobilité costale et respiration ample', 'bxUoYTZ68ik', 12, 'étirements', 'Bande de résistance', 'Libération profonde de la cage thoracique, augmentation du volume inspiratoire, meilleure oxygénation des tissus grâce à une résistance ciblée avec la bande.'),
  ('s2j5o13', 'marathon-4', 2, 5, 13, 'Semaine 2, jour 5 — Bassin fonctionnel', 'r6IgERqq0yk', 18, 'étirements', 'Ballon', 'Travail pelvien profond pour améliorer la circulation, relâcher les tensions et restaurer la mécanique naturelle des hanches. Modifiable sur chaise ou au sol si besoin.'),
  ('s2j6o14', 'marathon-4', 2, 6, 14, 'Semaine 2, jour 6 — Bassin et gainage profond', 'x_D23olbIdA', 11, 'étirements', 'Ballon', 'Synchronisation pelvienne, mobilité des hanches et circulation. Activation abdominale profonde associée à la respiration pour renforcer le soutien interne.'),
  ('s3j1o15', 'marathon-4', 3, 1, 15, 'Semaine 3, jour 1 — Mobilité costale et diaphragme', 'fUVJK_iQXRk', 11, 'étirements', 'Myo balles', 'Travail sur la mobilité de la cage thoracique. Le diaphragme s''attache aux côtes basses : plus la cage est mobile, plus la respiration peut s''amplifier naturellement.'),
  ('s3j2o16', 'marathon-4', 3, 2, 16, 'Semaine 3, jour 2 — Plancher pelvien, fessiers et hanches', 'Nmlryh6ed6k', 12, 'étirements', 'Myo balles', 'Travail en profondeur sur le plancher pelvien, les fessiers et les hanches — un système interconnecté qui stabilise le bassin et soutient la colonne.'),
  ('s3j2o17', 'marathon-4', 3, 2, 17, 'Semaine 3, jour 2 (bonus) — Massage abdominal doux', 'rInXc2uIPUU', 4, 'étirements', 'Myo balles', 'Vidéo optionnelle : massage doux à la balle pour détendre la zone abdominale, stimuler le transit et relâcher le diaphragme. Mouvements très légers, sans pression.'),
  ('s3j3o18', 'marathon-4', 3, 3, 18, 'Semaine 3, jour 3 — Travail profond de l''omoplate', 'dhlB-CyK67U', 20, 'étirements', 'Myo balles, serviette', 'Séance plus exigeante centrée sur l''omoplate et la cage thoracique. Rester très attentif aux sensations, arrêter immédiatement en cas de douleur vive.'),
  ('s3j4o19', 'marathon-4', 3, 4, 19, 'Semaine 3, jour 4 — Travail du plancher pelvien', 'UwgnumF-TAY', 10, 'étirements', 'Myo balles, foam roller', 'Travail du plancher pelvien, pièce centrale du système de soutien interne : posture, respiration, bas du dos et sangle abdominale en dépendent.'),
  ('s3j5o20', 'marathon-4', 3, 5, 20, 'Semaine 3, jour 5 — Synchronisation pelvienne et diaphragme', 'JHTNnnG1meY', 11, 'étirements', 'Serviette', 'Synchronisation entre ouverture du plancher pelvien, mobilité des hanches et diaphragme. Coordination entre diaphragme haut et bas, attention à la respiration et à l''axe du corps.'),
  ('s3j5o21', 'marathon-4', 3, 5, 21, 'Semaine 3, jour 5 (bonus) — Libération du visage', '3JcPDGq7jhw', 5, 'étirements', 'Myo balles', 'Vidéo bonus optionnelle : libération de la zone occipitale pour dégonfler le visage et relancer le drainage veineux et lymphatique.'),
  ('s3j6o22', 'marathon-4', 3, 6, 22, 'Semaine 3, jour 6 — Bassin et fessiers en profondeur', '6BbII6ve6zQ', 12, 'étirements', 'Myo balles, ballon', 'Travail profond du bassin et des fessiers aux balles souples, engagement des abdominaux profonds pour construire un soutien interne durable.'),
  ('s4j1o23', 'marathon-4', 4, 1, 23, 'Semaine 4, jour 1 — Plancher pelvien et respiration', 'd6FHn8kL9BA', 14, 'étirements', 'Ballon', 'Entrée dans la semaine 4 : travail plus profond et conscient, centré sur le plancher pelvien et sa connexion à la respiration et au mouvement.'),
  ('s4j2o24', 'marathon-4', 4, 2, 24, 'Semaine 4, jour 2 — Cage thoracique et respiration', '7QIR8DgffLc', 14, 'étirements', 'Ballon, bande de résistance', 'Travail de la cage thoracique et de la respiration, avec attention portée à la coordination entre diaphragme haut et diaphragme bas.'),
  ('s4j3o25', 'marathon-4', 4, 3, 25, 'Semaine 4, jour 3 — Bassin et psoas-iliaque', 'zzV7FgSdx78', 14, 'étirements', 'Myo balles', 'Travail aux balles souples sur le bassin et le psoas-iliaque, des zones souvent sursollicitées et peu conscientisées.'),
  ('s4j4o26', 'marathon-4', 4, 4, 26, 'Semaine 4, jour 4 — Gainage profond et respiration', '1g1Bz-l3mIo', 12, 'étirements', 'Myo balles, bande de résistance', 'Activation douce des abdominaux profonds coordonnée à la respiration, ouverture de la cage thoracique et retour au travail du bassin.'),
  ('s4j5o27', 'marathon-4', 4, 5, 27, 'Semaine 4, jour 5 — Gainage profond et plancher pelvien', 'm61ONDGSxkg', 13, 'étirements', 'Myo balles', 'Travail des abdominaux profonds, retour au plancher pelvien et à la respiration — les trois abordés comme un seul système interconnecté.'),
  ('s4j5o28', 'marathon-4', 4, 5, 28, 'Semaine 4, jour 5 (bonus) — Massage du buste', 'DeQyRos1pnU', 3, 'étirements', 'Myo balles', 'Vidéo bonus : massage doux du buste à la balle, avec travail de la zone xiphoïde et du diaphragme, à faible pression.'),
  ('s4j6o29', 'marathon-4', 4, 6, 29, 'Semaine 4, jour 6 — Plancher pelvien et mobilité du rachis', 'RuYbSrCwOLk', 13, 'étirements', 'Ballon', 'Travail profond du plancher pelvien combiné à la mobilité de la cage thoracique, du diaphragme et de la colonne.'),
  ('s4j6o30', 'marathon-4', 4, 6, 30, 'Semaine 4, jour 6 (bonus) — Travail des pieds', 'XMqZkuJC0Eo', 3, 'étirements', 'Myo balles', 'Vidéo bonus dédiée aux pieds, fondation du corps entier qui influence toute la chaîne posturale.'),
